"""House Robber III — tree DP returning (rob this node, skip this node).

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def rob(self, root) -> int:
        def solve(node):
            if not node:
                return 0, 0
            left_rob, left_skip = solve(node.left)
            right_rob, right_skip = solve(node.right)
            rob_here = node.val + left_skip + right_skip
            skip_here = max(left_rob, left_skip) + max(right_rob, right_skip)
            return rob_here, skip_here

        return max(solve(root))
